349	      environment: {
350	        ANTHROPIC_API_KEY_PARAMETER: ANTHROPIC_API_KEY_PARAMETER,
351	      },
352	      role: role,
353	      layers: [layer],
354	      timeout: cdk.Duration.seconds(30)
355	    });
356	
357	    const retrieveAndGeneratePodcastFunction = new lambda.Function(this, 'RetrieveAndGeneratePodcastFunction', {
358	      code: lambda.Code.fromAsset('src'),
359	      handler: 'rss_email.retrieve_and_generate_podcast.lambda_handler',
360	      runtime: lambda.Runtime.PYTHON_3_13,
361	      environment: {
362	        ANTHROPIC_API_KEY_PARAMETER: ANTHROPIC_API_KEY_PARAMETER,
363	        BUCKET: bucket.bucketName,
364	        PODCAST_CLOUDFRONT_DISTRIBUTION_ID: podcastDistribution.distributionId,
365	        PODCAST_CLOUDFRONT_DOMAIN_PARAMETER: PODCAST_CLOUDFRONT_DOMAIN_PARAMETER,
366	        PODCAST_LAST_RUN_PARAMETER: PODCAST_LAST_RUN_PARAMETER,
367	      },
368	      role: role,
369	      layers: [layer],
370	      memorySize: 512,
371	      timeout: cdk.Duration.seconds(300)
372	    });
373	
374	    // ===== Step Functions State Machine =====
375	
376	    // Number of 60s polls before backing off to a longer interval. Message
377	    // Batches can take a while, so hammering the status API every minute for
378	    // hours is wasteful once a batch is clearly not going to finish quickly.
379	    const POLL_BACKOFF_THRESHOLD = 5;
380	
381	    // Add a generic retry (with backoff) to a LambdaInvoke task so transient
382	    // failures inside a branch don't immediately cascade into a full Parallel
383	    // state failure (which would otherwise kill the sibling branch too).
384	    const withRetry = (task: tasks.LambdaInvoke): tasks.LambdaInvoke => {
385	      task.addRetry({
386	        errors: [sfn.Errors.ALL],
387	        interval: cdk.Duration.seconds(30),
388	        maxAttempts: 2,
389	        backoffRate: 2,
390	      });
391	      return task;
392	    };
393	
394	    // RSS Retrieval Task (first step)
395	    const retrieveArticlesTask = withRetry(new tasks.LambdaInvoke(this, 'Retrieve RSS Articles', {
396	      lambdaFunction: retrieveRSSArticlesFunction,
397	      outputPath: '$.Payload',
398	    }));
399	
400	    // Email Branch Tasks
401	    const submitEmailBatchTask = withRetry(new tasks.LambdaInvoke(this, 'Submit Email Batch', {
402	      lambdaFunction: submitEmailBatchFunction,
403	      resultPath: '$.emailBatch',
404	    }));
405	
406	    const checkEmailStatusTask = withRetry(new tasks.LambdaInvoke(this, 'Check Email Status', {
407	      lambdaFunction: checkEmailBatchStatusFunction,
408	      inputPath: '$.emailBatch.Payload',
409	      resultPath: '$.emailBatch',
410	    }));
411	
412	    const waitEmailShort = new sfn.Wait(this, 'Wait Email 60s', {
413	      time: sfn.WaitTime.duration(cdk.Duration.seconds(60)),
414	    });
415	
416	    const waitEmailLong = new sfn.Wait(this, 'Wait Email 5m', {
417	      time: sfn.WaitTime.duration(cdk.Duration.minutes(5)),
418	    });
419	
420	    const retrieveAndSendEmailTask = withRetry(new tasks.LambdaInvoke(this, 'Retrieve and Send Email', {
421	      lambdaFunction: retrieveAndSendEmailFunction,
422	      inputPath: '$.emailBatch.Payload',
423	      outputPath: '$.Payload',
424	    }));
425	
426	    const emailPollBackoffChoice = new sfn.Choice(this, 'Email Poll Backoff?')
427	      .when(
428	        sfn.Condition.numberLessThan('$.emailBatch.Payload.poll_count', POLL_BACKOFF_THRESHOLD),
429	        waitEmailShort.next(checkEmailStatusTask)
430	      )
431	      .otherwise(waitEmailLong.next(checkEmailStatusTask));
432	
433	    const emailChoice = new sfn.Choice(this, 'Is Email Batch Complete?')
434	      .when(
435	        sfn.Condition.stringEquals('$.emailBatch.Payload.processing_status', 'ended'),
436	        retrieveAndSendEmailTask
437	      )
438	      .otherwise(emailPollBackoffChoice);
439	
440	    const emailBranch = submitEmailBatchTask
441	      .next(checkEmailStatusTask)
442	      .next(emailChoice);
443	
444	    // Isolate the email branch inside its own single-branch Parallel so a
445	    // Catch here stops the failure from propagating to (and killing) the
446	    // podcast branch running alongside it.
447	    const emailBranchIsolated = new sfn.Parallel(this, 'Email Branch Isolated', {
448	      resultPath: '$.emailResult',
449	    }).branch(emailBranch);
450	
451	    const notifyEmailFailure = new tasks.SnsPublish(this, 'Notify Email Branch Failure', {
452	      topic: error_alerts_topic,
453	      subject: 'RSS workflow: email branch failed',
454	      message: sfn.TaskInput.fromJsonPathAt('$.emailBranchError.Cause'),
455	    });
456	
457	    const emailBranchFailed = new sfn.Pass(this, 'Email Branch Failed', {
458	      parameters: { status: 'failed', branch: 'email' },
459	    });
460	
461	    emailBranchIsolated.addCatch(notifyEmailFailure.next(emailBranchFailed), {
462	      resultPath: '$.emailBranchError',
463	    });
464	
465	    // Podcast Branch Tasks
466	    const submitPodcastBatchTask = withRetry(new tasks.LambdaInvoke(this, 'Submit Podcast Batch', {
467	      lambdaFunction: submitPodcastBatchFunction,
468	      resultPath: '$.podcastBatch',
469	    }));
470	
471	    const checkPodcastStatusTask = withRetry(new tasks.LambdaInvoke(this, 'Check Podcast Status', {
472	      lambdaFunction: checkPodcastBatchStatusFunction,
473	      inputPath: '$.podcastBatch.Payload',
474	      resultPath: '$.podcastBatch',
475	    }));
476	
477	    const waitPodcastShort = new sfn.Wait(this, 'Wait Podcast 60s', {
478	      time: sfn.WaitTime.duration(cdk.Duration.seconds(60)),
479	    });
480	
481	    const waitPodcastLong = new sfn.Wait(this, 'Wait Podcast 5m', {
482	      time: sfn.WaitTime.duration(cdk.Duration.minutes(5)),
483	    });
484	
485	    const retrieveAndGeneratePodcastTask = withRetry(new tasks.LambdaInvoke(this, 'Retrieve and Generate Podcast', {
486	      lambdaFunction: retrieveAndGeneratePodcastFunction,
487	      inputPath: '$.podcastBatch.Payload',
488	      outputPath: '$.Payload',
489	    }));
490	
491	    const podcastPollBackoffChoice = new sfn.Choice(this, 'Podcast Poll Backoff?')
492	      .when(
493	        sfn.Condition.numberLessThan('$.podcastBatch.Payload.poll_count', POLL_BACKOFF_THRESHOLD),
494	        waitPodcastShort.next(checkPodcastStatusTask)
495	      )
496	      .otherwise(waitPodcastLong.next(checkPodcastStatusTask));
497	
498	    const podcastChoice = new sfn.Choice(this, 'Is Podcast Batch Complete?')
499	      .when(
500	        sfn.Condition.stringEquals('$.podcastBatch.Payload.processing_status', 'ended'),
501	        retrieveAndGeneratePodcastTask
502	      )
503	      .otherwise(podcastPollBackoffChoice);
504	
505	    const podcastBranch = submitPodcastBatchTask
506	      .next(checkPodcastStatusTask)
507	      .next(podcastChoice);
508	
509	    // Isolate the podcast branch the same way as the email branch above.
510	    const podcastBranchIsolated = new sfn.Parallel(this, 'Podcast Branch Isolated', {
511	      resultPath: '$.podcastResult',
512	    }).branch(podcastBranch);
513	
514	    const notifyPodcastFailure = new tasks.SnsPublish(this, 'Notify Podcast Branch Failure', {
515	      topic: error_alerts_topic,
516	      subject: 'RSS workflow: podcast branch failed',
517	      message: sfn.TaskInput.fromJsonPathAt('$.podcastBranchError.Cause'),
518	    });
519	
520	    const podcastBranchFailed = new sfn.Pass(this, 'Podcast Branch Failed', {
521	      parameters: { status: 'failed', branch: 'podcast' },
522	    });
523	
524	    podcastBranchIsolated.addCatch(notifyPodcastFailure.next(podcastBranchFailed), {
525	      resultPath: '$.podcastBranchError',
526	    });
527	
528	    // Parallel Processing
529	    const parallelState = new sfn.Parallel(this, 'Process Email and Podcast', {
530	      resultPath: '$.results',
531	    })
532	      .branch(emailBranchIsolated)
533	      .branch(podcastBranchIsolated);
534	
535	    // Success State
536	    const successState = new sfn.Succeed(this, 'Workflow Complete');
537	
538	    // Define complete workflow: Retrieve Articles -> Parallel Processing -> Success
539	    const definition = retrieveArticlesTask
540	      .next(parallelState)
541	      .next(successState);
542	
543	    // Create State Machine
544	    const stateMachine = new sfn.StateMachine(this, 'DailyRSSNewsletterWorkflow', {
545	      definitionBody: sfn.DefinitionBody.fromChainable(definition),
546	      // The Message Batches API SLA window is 24h; give the workflow enough
547	      // headroom that a slow batch doesn't time out the execution just
548	      // before the (already paid for) results become available.
549	      timeout: cdk.Duration.hours(25),
550	      comment: 'Orchestrates daily RSS newsletter: process email & podcast in parallel using Message Batches API',
551	    });
552	
553	    // Grant Step Functions permission to invoke Lambda functions
554	    retrieveRSSArticlesFunction.grantInvoke(stateMachine);
555	    submitEmailBatchFunction.grantInvoke(stateMachine);
556	    checkEmailBatchStatusFunction.grantInvoke(stateMachine);
557	    retrieveAndSendEmailFunction.grantInvoke(stateMachine);
558	    submitPodcastBatchFunction.grantInvoke(stateMachine);
559	    checkPodcastBatchStatusFunction.grantInvoke(stateMachine);
560	    retrieveAndGeneratePodcastFunction.grantInvoke(stateMachine);
561	
562	    // Update EventBridge rule to trigger Step Function instead of Lambda
563	    // Replace the emailerEventRule to trigger the state machine
564	    const dailyNewsletterRule = new events.Rule(this, 'dailyNewsletterRule', {
565	      schedule: events.Schedule.cron({ minute: '30', hour: '7', weekDay: '2-6' }),
566	      description: 'Trigger daily RSS newsletter workflow with Message Batches API',
567	    });
568	
569	    dailyNewsletterRule.addTarget(
570	      new targets.SfnStateMachine(stateMachine, {
571	        input: events.RuleTargetInput.fromObject({
572	          trigger: 'scheduled',
573	          timestamp: events.EventField.time,
574	        }),
575	      })
576	    );
577	
578	    // Manual trigger via email: SNS topic -> Lambda trigger -> Step Functions
579	    // When someone sends an email to the configured address, SES publishes to receive_topic
580	    // A small Lambda function listens to the topic and starts the Step Functions workflow
581	    const manualTriggerFunction = new lambda.Function(this, 'ManualTriggerFunction', {
582	      code: lambda.Code.fromInline(`
583	import boto3
584	import json
585	import os
586	
587	def lambda_handler(event, context):
588	    """Trigger Step Functions workflow when email is received.
589	
590	    Validates the sender against ALLOWED_SENDER_EMAIL (the old is_valid_email
591	    check the SES-receipt-rule flow used to perform) and skips starting a new
592	    execution if one is already running, to avoid double-sending the digest
593	    and double Claude spend from concurrent triggers.
594	    """
595	    sfn = boto3.client('stepfunctions')
596	    state_machine_arn = os.environ['STATE_MACHINE_ARN']
597	    allowed_sender = os.environ.get('ALLOWED_SENDER_EMAIL', '').lower()
598	
599	    sns_message = json.loads(event['Records'][0]['Sns']['Message'])
600	    sender = sns_message.get('mail', {}).get('source', '').lower()
601	
602	    if allowed_sender and sender != allowed_sender:
603	        print(f"Ignoring trigger from unauthorized sender: {sender}")
604	        return {'statusCode': 200, 'started': False, 'reason': 'unauthorized_sender'}
605	
606	    running = sfn.list_executions(
607	        stateMachineArn=state_machine_arn,
608	        statusFilter='RUNNING',
609	        maxResults=1,
610	    )
611	    if running.get('executions'):
612	        existing_arn = running['executions'][0]['executionArn']
613	        print(f"Execution already running ({existing_arn}), skipping start")
614	        return {'statusCode': 200, 'started': False, 'reason': 'already_running'}
615	
616	    # Start execution
617	    response = sfn.start_execution(
618	        stateMachineArn=state_machine_arn,
619	        input=json.dumps({
620	            'trigger': 'manual',
621	            'timestamp': event['Records'][0]['Sns']['Timestamp']
622	        })
623	    )
624	
625	    print(f"Started execution: {response['executionArn']}")
626	    return {'statusCode': 200, 'started': True, 'executionArn': response['executionArn']}
627	      `),
628	      handler: 'index.lambda_handler',
629	      runtime: lambda.Runtime.PYTHON_3_13,
630	      timeout: cdk.Duration.seconds(30),
631	      environment: {
632	        STATE_MACHINE_ARN: stateMachine.stateMachineArn,
633	        ALLOWED_SENDER_EMAIL: TO_EMAIL_ADDRESS,
634	      }
635	    });
636	
637	    // Grant permission to start Step Functions execution and to list
638	    // executions (for the concurrency guard above)
639	    stateMachine.grantStartExecution(manualTriggerFunction);
640	    manualTriggerFunction.addToRolePolicy(new iam.PolicyStatement({
641	      effect: iam.Effect.ALLOW,
642	      actions: ['states:ListExecutions'],
643	      resources: [stateMachine.stateMachineArn],
644	    }));
645	
646	    // Subscribe Lambda to SNS topic
647	    receive_topic.addSubscription(new sns_subscriptions.LambdaSubscription(manualTriggerFunction));
648	
649	    // Add Polly permissions to the role
650	    role.addToPolicy(new iam.PolicyStatement({
651	      effect: iam.Effect.ALLOW,
652	      actions: ['polly:SynthesizeSpeech'],
653	      resources: ['*']
654	    }));
655	
656	    // Add SSM permission for podcast last run
657	    role.addToPolicy(new iam.PolicyStatement({
658	      effect: iam.Effect.ALLOW,
659	      actions: ['ssm:PutParameter', 'ssm:GetParameter'],
660	      resources: [`arn:aws:ssm:*:*:parameter/${PODCAST_LAST_RUN_PARAMETER}`],
661	    }));
662	
663	    // Add SSM permission for CloudFront domain parameter
664	    role.addToPolicy(new iam.PolicyStatement({
665	      effect: iam.Effect.ALLOW,
666	      actions: ['ssm:GetParameter'],
667	      resources: [`arn:aws:ssm:*:*:parameter/${PODCAST_CLOUDFRONT_DOMAIN_PARAMETER}`],
668	    }));
669	
670	    // Add CloudFront invalidation permissions
671	    role.addToPolicy(new iam.PolicyStatement({
672	      effect: iam.Effect.ALLOW,
673	      actions: ['cloudfront:CreateInvalidation'],
674	      resources: [`arn:aws:cloudfront::${this.account}:distribution/${podcastDistribution.distributionId}`]
675	    }));
676	
677	    // Add bucket policy to restrict CloudFront access to only /podcasts/* prefix
678	    bucket.addToResourcePolicy(new iam.PolicyStatement({
679	      sid: 'AllowCloudFrontServicePrincipalReadOnly',
680	      effect: iam.Effect.ALLOW,
681	      principals: [new iam.ServicePrincipal('cloudfront.amazonaws.com')],
682	      actions: ['s3:GetObject'],
683	      resources: [bucket.arnForObjects('podcasts/*')],
684	      conditions: {
685	        'StringEquals': {
686	          'AWS:SourceArn': `arn:aws:cloudfront::${this.account}:distribution/${podcastDistribution.distributionId}`
687	        }
688	      }
689	    }));
690	
691	    // Store CloudFront domain in Parameter Store for Lambda to use
692	    new ssm.StringParameter(this, 'PodcastCloudFrontDomainParameter', {
693	      parameterName: PODCAST_CLOUDFRONT_DOMAIN_PARAMETER,
694	      stringValue: podcastDistribution.distributionDomainName,
695	      description: 'CloudFront distribution domain for podcast RSS feed',
696	      tier: ssm.ParameterTier.STANDARD,
697	    });
698	
699	    // Old rssEmailLogGroup, emailerErrorMetricFilter, and errorAlarm removed
700	    // RSSEmailerFunction replaced by Step Functions workflow
701	
702	    // Reference the function's log group directly (Lambda auto-creates it; logRetention Custom Resource manages retention)
703	    const retrieveRSSArticlesLogGroup = retrieveRSSArticlesFunction.logGroup;
704	
705	    const retrieveRSSArticlesErrorMetricFilter = new logs.MetricFilter(this, 'RetrieveRSSArticlesErrorMetricFilter', {
706	      logGroup: retrieveRSSArticlesLogGroup,
707	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
708	      metricNamespace: 'RSS/RetrieveRSSArticlesLambda',
709	      metricName: 'ErrorWarningCount',
710	      defaultValue: 0,
711	      metricValue: '1',
712	    });
713	
714	    const retrieveRSSArticlesErrorAlarm = new cdk.aws_cloudwatch.Alarm(this, 'RetrieveRSSArticlesLambdaErrorAlarm', {
715	      metric: retrieveRSSArticlesErrorMetricFilter.metric(),
716	      threshold: 1,
717	      evaluationPeriods: 1,
718	      comparisonOperator: cdk.aws_cloudwatch.ComparisonOperator.GREATER_THAN_OR_EQUAL_TO_THRESHOLD,
719	      treatMissingData: cdk.aws_cloudwatch.TreatMissingData.NOT_BREACHING,
720	      alarmDescription: 'Alarm for ERROR or WARNING log messages in RetrieveRSSArticles Lambda',
721	      actionsEnabled: true,
722	    });
723	
724	    retrieveRSSArticlesErrorAlarm.addAlarmAction(new cloudwatch_actions.SnsAction(error_alerts_topic));
725	
726	    // Alarm on the workflow itself failing (e.g. a top-level task exhausting
727	    // its retries before a branch Catch could even isolate it), rather than
728	    // relying solely on log-grep alarms per Lambda.
729	    const stateMachineExecutionsFailedAlarm = new cdk.aws_cloudwatch.Alarm(this, 'StateMachineExecutionsFailedAlarm', {
730	      metric: stateMachine.metricFailed({ period: cdk.Duration.minutes(5) }),
731	      threshold: 1,
732	      evaluationPeriods: 1,
733	      comparisonOperator: cdk.aws_cloudwatch.ComparisonOperator.GREATER_THAN_OR_EQUAL_TO_THRESHOLD,
734	      treatMissingData: cdk.aws_cloudwatch.TreatMissingData.NOT_BREACHING,
735	      alarmDescription: 'Alarm when the daily RSS newsletter Step Functions execution fails',
736	      actionsEnabled: true,
737	    });
738	
739	    stateMachineExecutionsFailedAlarm.addAlarmAction(new cloudwatch_actions.SnsAction(error_alerts_topic));
740	
741	    // Create a Lambda function that will forward log events to the SNS topic
742	    const logForwarderFunction = new lambda.Function(this, 'LogForwarderFunction', {
743	      runtime: lambda.Runtime.NODEJS_22_X,
744	      handler: 'rss_email/log_forwarder.handler',
745	      code: lambda.Code.fromAsset('src'),
746	      environment: {
747	        SNS_TOPIC_ARN: error_alerts_topic.topicArn
748	      },
749	      timeout: cdk.Duration.minutes(5), // Increased timeout to handle aggregation
750	      memorySize: 256 // Increased memory for log aggregation
751	    });
752	
753	    // Grant the Lambda function necessary permissions
754	    error_alerts_topic.grantPublish(logForwarderFunction);
755	
756	    // Add CloudWatch Logs permissions
757	    logForwarderFunction.addToRolePolicy(new iam.PolicyStatement({
758	      effect: iam.Effect.ALLOW,
759	      actions: [
760	        'logs:CreateLogGroup',
761	        'logs:CreateLogStream',
762	        'logs:PutLogEvents',
763	        'logs:DescribeLogStreams'
764	      ],
765	      resources: ['*']
766	    }));
767	
768	    // Create log subscription filters to send the actual log messages to the SNS topic via Lambda
769	    // This ensures the actual log message content is included in the notification
770	    // Old emailerLogSubscription removed - RSSEmailerFunction replaced by Step Functions workflow
771	
772	    new logs.SubscriptionFilter(this, 'RetrieveRSSArticlesLogSubscription', {
773	      logGroup: retrieveRSSArticlesLogGroup,
774	      destination: new destinations.LambdaDestination(logForwarderFunction),
775	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
776	    });
777	
778	    // Old podcastLogGroup removed - replaced by batch processing log groups below
779	
780	    // Log groups for batch processing Lambda functions
781	    const submitEmailBatchLogGroup = new logs.LogGroup(this, 'submitEmailBatchLogGroup', {
782	      logGroupName: `/aws/lambda/${submitEmailBatchFunction.functionName}`,
783	      retention: logs.RetentionDays.ONE_MONTH,
784	      removalPolicy: cdk.RemovalPolicy.DESTROY
785	    });
786	
787	    new logs.SubscriptionFilter(this, 'SubmitEmailBatchLogSubscription', {
788	      logGroup: submitEmailBatchLogGroup,
789	      destination: new destinations.LambdaDestination(logForwarderFunction),
790	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
791	    });
792	
793	    const checkEmailBatchStatusLogGroup = new logs.LogGroup(this, 'checkEmailBatchStatusLogGroup', {
794	      logGroupName: `/aws/lambda/${checkEmailBatchStatusFunction.functionName}`,
795	      retention: logs.RetentionDays.ONE_MONTH,
796	      removalPolicy: cdk.RemovalPolicy.DESTROY
797	    });
798	
799	    new logs.SubscriptionFilter(this, 'CheckEmailBatchStatusLogSubscription', {
800	      logGroup: checkEmailBatchStatusLogGroup,
801	      destination: new destinations.LambdaDestination(logForwarderFunction),
802	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
803	    });
804	
805	    const retrieveAndSendEmailLogGroup = new logs.LogGroup(this, 'retrieveAndSendEmailLogGroup', {
806	      logGroupName: `/aws/lambda/${retrieveAndSendEmailFunction.functionName}`,
807	      retention: logs.RetentionDays.ONE_MONTH,
808	      removalPolicy: cdk.RemovalPolicy.DESTROY
809	    });
810	
811	    new logs.SubscriptionFilter(this, 'RetrieveAndSendEmailLogSubscription', {
812	      logGroup: retrieveAndSendEmailLogGroup,
813	      destination: new destinations.LambdaDestination(logForwarderFunction),
814	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
815	    });
816	
817	    const submitPodcastBatchLogGroup = new logs.LogGroup(this, 'submitPodcastBatchLogGroup', {
818	      logGroupName: `/aws/lambda/${submitPodcastBatchFunction.functionName}`,
819	      retention: logs.RetentionDays.ONE_MONTH,
820	      removalPolicy: cdk.RemovalPolicy.DESTROY
821	    });
822	
823	    new logs.SubscriptionFilter(this, 'SubmitPodcastBatchLogSubscription', {
824	      logGroup: submitPodcastBatchLogGroup,
825	      destination: new destinations.LambdaDestination(logForwarderFunction),
826	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
827	    });
828	
829	    const checkPodcastBatchStatusLogGroup = new logs.LogGroup(this, 'checkPodcastBatchStatusLogGroup', {
830	      logGroupName: `/aws/lambda/${checkPodcastBatchStatusFunction.functionName}`,
831	      retention: logs.RetentionDays.ONE_MONTH,
832	      removalPolicy: cdk.RemovalPolicy.DESTROY
833	    });
834	
835	    new logs.SubscriptionFilter(this, 'CheckPodcastBatchStatusLogSubscription', {
836	      logGroup: checkPodcastBatchStatusLogGroup,
837	      destination: new destinations.LambdaDestination(logForwarderFunction),
838	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
839	    });
840	
841	    const retrieveAndGeneratePodcastLogGroup = new logs.LogGroup(this, 'retrieveAndGeneratePodcastLogGroup', {
842	      logGroupName: `/aws/lambda/${retrieveAndGeneratePodcastFunction.functionName}`,
843	      retention: logs.RetentionDays.ONE_MONTH,
844	      removalPolicy: cdk.RemovalPolicy.DESTROY
845	    });
846	
847	    new logs.SubscriptionFilter(this, 'RetrieveAndGeneratePodcastLogSubscription', {
848	      logGroup: retrieveAndGeneratePodcastLogGroup,
849	      destination: new destinations.LambdaDestination(logForwarderFunction),
850	      filterPattern: logs.FilterPattern.anyTerm('ERROR', 'WARNING', 'Error', 'Warning', 'error', 'warning'),
851	    });
852	
853	    // Output the CloudFront URL for the podcast feed
854	    new cdk.CfnOutput(this, 'PodcastFeedUrl', {
855	      value: `https://${podcastDistribution.distributionDomainName}/podcasts/feed.xml`,
856	      description: 'Public URL for the podcast RSS feed',
857	      exportName: 'PodcastFeedUrl',
858	    });
859	
860	    new cdk.CfnOutput(this, 'PodcastDistributionDomain', {
861	      value: podcastDistribution.distributionDomainName,
862	      description: 'CloudFront distribution domain for podcast content',
863	      exportName: 'PodcastDistributionDomain',
864	    });
865	  }
866	}
